/**
 * HuggingFace 模型商城前端模块（P2-5 重写：移除 innerHTML 内联 style）
 */
(function() {
'use strict';
var _res=[], _queue=[], _selId=null, _files=[];
function fs(b){if(!b)return '--';var u=['B','KB','MB','GB'];var i=0,s=b;while(s>=1024&&i<u.length-1){s/=1024;i++;}return s.toFixed(1)+' '+u[i];}
function fd(n){if(!n)return '—';return n>=1e6?(n/1e6).toFixed(1)+'M':n>=1e3?(n/1e3).toFixed(1)+'K':n;}
function toast(m,t){var c=document.getElementById('toastContainer');if(!c)return;t=t||'info';var icon={'success':'✓','error':'✕','warning':'!','info':'i'}[t]||'i';var e=document.createElement('div');e.className='toast '+t;e.innerHTML='<span class="toast-icon">'+icon+'</span><span class="toast-text"></span><button class="toast-close" type="button" aria-label="关闭">×</button>';e.querySelector('.toast-text').textContent=m;c.appendChild(e);requestAnimationFrame(function(){e.classList.add('show');});var removed=false;function rm(){if(removed)return;removed=true;e.classList.remove('show');setTimeout(function(){e.remove();},260);}e.querySelector('.toast-close').addEventListener('click',rm);setTimeout(rm,3000);}
function classifyError(e){if(!e)return '操作失败：未知错误';var s=String(e);if(/429|限流|rate.?limit/i.test(s))return '请求被限流，请稍后重试或在设置中填入 HF Token';if(/401|403|token|unauthor/i.test(s))return '权限不足或 Token 无效，请检查 HF Token 设置';if(/404|not.?found|存在|未找到/i.test(s))return '资源未找到，请检查 model_id / filename 是否正确';if(/io|disk|空间|permission|拒绝|denied|space|disk|ENOENT/i.test(s))return '文件系统错误：'+s;if(/network|connection|timeout|代理|proxy|ssl|handshake/i.test(s))return '网络错误，请检查代理或稍后重试';if(/非法.*model_id|非法.*文件名|sanitize|traversal/i.test(s))return '参数被安全规则拒绝：'+s;return '操作失败：'+s;}
async function openM(){try{await window.__TAURI__.core.invoke('open_hf_store_window');await loadS();}catch(e){console.error(e);toast(classifyError(e),'error');}}
async function loadS(){try{var t=await window.__TAURI__.core.invoke('get_hf_token');var ti=document.getElementById('hfTokenInput');if(ti&&t)ti.value='********';var d=await window.__TAURI__.core.invoke('get_hf_download_dir');var di=document.getElementById('hfDownloadDirInput');if(di){if(!di.placeholder||di.placeholder==='加载中...')di.placeholder=d;di.value=d;}}catch(e){console.error(e);}}
async function search(q){if(!q||!q.trim())return;document.getElementById('hfEmptyState').style.display='none';var ls=document.getElementById('hfLoadingState');ls.removeAttribute('hidden');document.getElementById('hfModelsContainer').innerHTML='';document.getElementById('hfDetailPanel').setAttribute('hidden','');var to=setTimeout(function(){document.getElementById('hfModelsContainer').innerHTML='<p class="hf-msg-error">搜索超时（网络过慢或被限流），请稍后重试或设置 HF Token</p>';ls.setAttribute('hidden','');},35000);try{var r=await window.__TAURI__.core.invoke('search_hf_models',{query:q.trim(),limit:30});clearTimeout(to);_res=r;renderR(r);}catch(e){clearTimeout(to);console.error(e);document.getElementById('hfModelsContainer').innerHTML='<p class="hf-msg-error">'+classifyError(e)+'</p>';}finally{clearTimeout(to);ls.setAttribute('hidden','');}}
async function viewF(mid){_selId=mid;document.getElementById('hfDetailModelId').textContent=mid;document.getElementById('hfDetailBody').innerHTML='<div class="hf-detail-loading"><div class="spinner"></div><p>正在获取模型文件列表...</p></div>';var dp=document.getElementById('hfDetailPanel');if(dp)dp.removeAttribute('hidden');var to=setTimeout(function(){var b=document.getElementById('hfDetailBody');if(b)b.innerHTML='<p class="hf-msg-error">加载超时（网络过慢或被限流），请稍后重试或设置 HF Token</p>';},35000);try{var f=await window.__TAURI__.core.invoke('get_hf_model_files',{modelId:mid});clearTimeout(to);_files=f;renderF(mid,f);}catch(e){clearTimeout(to);console.error(e);document.getElementById('hfDetailBody').innerHTML='<p class="hf-msg-danger">加载失败: '+classifyError(e)+'</p>';}}
function renderR(models){var c=document.getElementById('hfModelsContainer');if(!models||!models.length){c.innerHTML='<p class="hf-msg-muted">未找到相关模型</p>';return;}var html='';for(var i=0;i<models.length;i++){var m=models[i];var tags='';for(var j=0;j<m.tags.length&&j<4;j++){tags+='<span class="hf-model-tag">'+m.tags[j]+'</span>';}html+='<div class="hf-model-card" data-v="'+m.id+'">'+'<div class="hf-model-card-header"><div class="hf-model-id">'+m.id.split('/').slice(1).join('/')+'</div></div><div class="hf-model-stats"><span>↓ '+fd(m.downloads)+'</span><span>♥ '+fd(m.likes)+'</span></div>'+(m.description?'<div class="hf-model-desc">'+m.description+'</div>':'')+'<div class="hf-model-tags">'+tags+'</div></div>';}c.innerHTML=html;c.querySelectorAll('[data-v]').forEach(function(b){b.addEventListener('click',function(){if(b.hasAttribute('disabled'))return;viewF(b.dataset.v);});});}
function renderF(mid,files){var b=document.getElementById('hfDetailBody');if(!files||!files.length){b.innerHTML='<p class="hf-msg-muted">该模型暂无文件</p>';return;}function parseQuant(p){var m=p.match(/[.-]([QIF][0-9]+(?:_[KS])?)(?:[.-]|$)/i);return m?m[1].toUpperCase():null}function ellipsis(p,max){if(p.length<=max)return p;var head=Math.ceil((max-1)/2);var tail=Math.floor((max-1)/2);return p.slice(0,head)+'…'+p.slice(p.length-tail)}var top='';if(files.length>1){top='<div class="hf-detail-toolbar"><span class="hf-detail-toolbar-count">共 '+files.length+' 个 GGUF 文件</span><button class="btn-primary hf-detail-toolbar-btn" id="hfDownloadAllBtn">全部下载</button></div>'}var html=top;for(var i=0;i<files.length;i++){var f=files[i];var fid='hf-dl-'+mid.replace(/[^a-z0-9]/gi,'-')+'-'+f.path.replace(/[^a-z0-9]/gi,'-').replace(/[.]/g,'_');var sz=f.size||f.file_size||0;var fname=f.path.split('/').pop();html+='<div class="hf-file-row" data-d="'+fid+'"><span class="hf-file-name" title="'+escapeHtml(f.path)+'" data-fmid="'+mid+'" data-fpath="'+escapeHtml(f.path)+'">'+escapeHtml(fname)+'</span><span class="hf-file-size">'+fs(sz)+'</span><button class="btn-primary hf-file-download-btn" data-fid="'+fid+'" data-fpath="'+escapeHtml(f.path)+'" data-fmid="'+mid+'" data-fsize="'+sz+'">下载</button></div>';}b.innerHTML=html;b.querySelectorAll('.hf-file-download-btn').forEach(function(btn){btn.addEventListener('click',function(){var fpath=btn.dataset.fpath;var fmid=btn.dataset.fmid;var fsize=parseInt(btn.dataset.fsize)||0;btn.disabled=true;btn.textContent='排队中…';startD(fmid,fpath,fsize);});});b.querySelectorAll('.hf-file-name[data-fmid]').forEach(function(nameEl){nameEl.style.cursor='pointer';nameEl.title='点击复制下载链接';nameEl.addEventListener('click',function(){var fmid=this.dataset.fmid;var fpath=this.dataset.fpath;var fname=fpath.split('/').pop();var dlUrl='https://huggingface.co/'+fmid+'/resolve/main/'+encodeURIComponent(fname);if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(dlUrl).then(function(){toast('已复制下载链接: '+fname,'success');}).catch(function(){toast('复制失败，请手动复制','error');});}else{var ta=document.createElement('textarea');ta.value=dlUrl;document.body.appendChild(ta);ta.select();document.execCommand('copy');document.body.removeChild(ta);toast('已复制下载链接: '+fname,'success');}})});var allBtn=document.getElementById('hfDownloadAllBtn');if(allBtn){allBtn.addEventListener('click',function(){toast('开始批量下载 '+files.length+' 个文件','info');allBtn.disabled=true;allBtn.textContent='排队中…';for(var i=0;i<files.length;i++){var f=files[i];startD(mid,f.path,f.size||0);}});}}
function escapeHtml(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}
function renderDl(it){var el=document.getElementById(it.id);var st=it.st,pg=Math.min(100,Math.round((it.p||0)*100));var dlSize=(it.dl||0),tlSize=(it.tl||0);var sp=(it.sp||0);var fn=it.fn.split('/').pop();var sizeStr=tlSize>0?(fs(dlSize)+' / '+fs(tlSize)):(it.sz?fs(it.sz):'—');var speedStr=(st==='downloading'&&sp>0)?(' '+fs(sp)+'/s'):'';var etaStr=(st==='downloading'&&it.et>0&&sp>0)?(' · '+formatEta(it.et)):'';var icon=st==='complete'?'✔':st==='error'?'✖':st==='downloading'?'▶':'⏸';var label=st==='complete'?'完成':st==='error'?'失败':st==='downloading'?pg+'%':'等待';var ic=st==='complete'?'complete':st==='error'?'error':st==='downloading'?'downloading':'pending';var barCls='hf-dl-bar-fill-'+(st==='complete'?'complete':st==='error'?'error':'downloading');var pctCls='hf-dl-percent-'+(st==='complete'?'complete':st==='error'?'error':st==='downloading'?'downloading':'pending');var html='<div class="hf-dl-row-inner"><span class="hf-dl-icon hf-dl-icon-'+ic+'">'+icon+'</span><div class="hf-dl-body"><div class="hf-dl-bar-row"><div class="hf-dl-bar-track"><div class="hf-dl-bar-fill '+barCls+'"></div></div><span class="hf-dl-percent '+pctCls+'">'+label+'</span></div><div class="hf-dl-name" title="'+escapeHtml(fn)+'">'+escapeHtml(fn)+'</div><div class="hf-dl-info">'+escapeHtml(sizeStr+speedStr+etaStr)+'</div></div><button class="hf-dl-remove" title="移除" data-id="'+it.id+'">×</button></div>';if(!el){el=document.createElement('div');el.id=it.id;el.className='hf-dl-row';var list=document.getElementById('hfDownloadsList');if(list)list.appendChild(el);}el.innerHTML=html;el.querySelector('.hf-dl-bar-fill').style.width=pg+'%';var empty=document.getElementById('hfEmptyDl');if(empty)empty.style.display='none';}
function formatEta(secs){if(secs<60)return Math.round(secs)+'秒';if(secs<3600)return Math.floor(secs/60)+'分'+Math.round(secs%60)+'秒';return Math.floor(secs/3600)+'时'+Math.floor((secs%3600)/60)+'分';}
function startD(mid,fn,sz){var dl='hf-dl-'+mid.replace(/[^a-z0-9]/gi,'-')+'-'+fn.replace(/[^a-z0-9]/gi,'-');if(_queue.find(function(d){return d.id===dl;}))return;
    // 下载前确认弹窗（防误触），附带镜像源复选框
    var fname=fn.split('/').pop();
    var confirmed=await window.showConfirm({
      title:'确认下载',
      body:'模型：'+mid+'\n文件：'+fname+ (sz>0?'\n大小：'+fs(sz):''),
      confirmText:'开始下载',
      cancelText:'取消',
      checkbox:{label:'使用镜像源 hf-mirror.com（加速下载）',default:false}
    });
    if(!confirmed.confirmed)return;
    var useMirror=confirmed.checkbox;
    var it={id:dl,mid:mid,fn:fn,sz:sz||0,st:'downloading',p:0,dl:0,tl:sz||0,sp:0,et:0,path:''};_queue.push(it);renderDl(it);updateDc();var panel=document.getElementById('hfDownloadsPanel');if(panel&&panel.dataset.open!=='1')toggleDlPanel();(async function(){try{var r=await window.__TAURI__.core.invoke('download_hf_model',{modelId:mid,filename:fn,installDir:null,use_mirror:useMirror,expected_size:sz||0});it.st='complete';it.p=1;it.dl=it.tl||(r.file_size||0);it.path=r.path;renderDl(it);updateDc();toast('下载完成: '+fn,'success');setTimeout(function(){removeDl(it.id);},4000);}catch(e){console.error(e);it.st='error';renderDl(it);updateDc();toast('下载失败: '+e,'error');setTimeout(function(){removeDl(it.id);},6000);}})();}
function removeDl(id){var it=_queue.find(function(d){return d.id===id;});_queue=_queue.filter(function(d){return d.id!==id;});var el=document.getElementById(id);if(el)el.remove();updateDc();if(it&&it.st==='downloading'){try{window.__TAURI__.core.invoke('cancel_hf_download',{modelId:it.mid||'',filename:it.fn.split('/').pop()});}catch(e){console.error('cancel_hf_download failed:',e);}}}
function updateDc(){var n=_queue.length;var badge=document.getElementById('hfDlBadge');if(badge)badge.textContent=n;var cnt=document.getElementById('hfDownloadsCount');if(cnt)cnt.textContent=n;var empty=document.getElementById('hfEmptyDl');if(empty)empty.style.display=n>0?'none':'';}
function toggleDlPanel(){var p=document.getElementById('hfDownloadsPanel');if(!p)return;var open=p.dataset.open!=='1';p.dataset.open=open?'1':'0';p.classList.toggle('show',open);}
function init(){if(!document.getElementById('hfDownloadsPanel')){var fp=document.createElement('div');fp.id='hfDownloadsPanel';fp.dataset.open='0';fp.className='hf-dl-panel';fp.innerHTML='<div class="hf-dl-panel-header"><div class="hf-dl-panel-title"><span>⬇</span><span>下载队列</span></div><div class="hf-dl-panel-actions"><span id="hfDownloadsCount" class="hf-dl-panel-count">0</span><button id="hfCloseDlBtn" class="hf-dl-panel-close" title="关闭">×</button></div></div><div id="hfDownloadsList" class="hf-dl-panel-list"><p id="hfEmptyDl" class="hf-dl-panel-empty">暂无下载任务</p></div>';document.body.appendChild(fp);document.getElementById('hfCloseDlBtn').addEventListener('click',toggleDlPanel);var fab=document.getElementById('hfDlFab');if(fab)fab.addEventListener('click',toggleDlPanel);}var inStore=!!document.getElementById('hfResultsList');if(inStore){loadS();}var si=document.getElementById('hfSearchInput');if(si)si.addEventListener('keydown',function(e){if(e.key==='Enter')search(si.value);});var sb=document.getElementById('hfSearchBtn');if(sb)sb.addEventListener('click',function(){search(document.getElementById('hfSearchInput').value);});var bb=document.getElementById('hfBackBtn');if(bb)bb.addEventListener('click',function(){var dp=document.getElementById('hfDetailPanel');dp.setAttribute('hidden','');dp.style.display='';});var ts=document.getElementById('hfTokenSaveBtn');if(ts)ts.addEventListener('click',async function(){var t=document.getElementById('hfTokenInput').value.trim();if(!t){toast('请输入Token','warning');return;}try{await window.__TAURI__.core.invoke('set_hf_token',{token:t});document.getElementById('hfTokenInput').value='********';toast('Token已保存','success');}catch(e){toast('保存失败','error');}});var ds=document.getElementById('hfDownloadDirSaveBtn');if(ds)ds.addEventListener('click',async function(){var d=document.getElementById('hfDownloadDirInput').value.trim();if(!d){toast('请输入目录','warning');return;}try{await window.__TAURI__.core.invoke('set_hf_download_dir',{dir:d});toast('目录已保存','success');}catch(e){toast('保存失败','error');}});window.__TAURI__.event.listen('hf-download-progress',function(ev){var p=ev.payload;var dl='hf-dl-'+p.model_id.replace(/[^a-z0-9]/gi,'-')+'-'+p.filename.replace(/[^a-z0-9]/gi,'-');var it=_queue.find(function(d){return d.id===dl;});if(it){it.did=p.download_id;it.st=p.stage==='complete'?'complete':p.stage==='error'?'error':'downloading';it.p=Math.min(1,(p.progress||0));it.dl=p.downloaded||0;it.tl=p.total||0;it.sp=p.speed||0;it.et=p.eta||0;renderDl(it);}else if(p.stage==='init'){var nit={id:dl,mid:p.model_id,fn:p.filename,sz:0,st:'downloading',p:0,dl:0,tl:0,sp:0,et:0,path:'',did: p.download_id||''};_queue.push(nit);renderDl(nit);updateDc();}});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
